function change(fn,record=true){const old=current.current;if(!old)return;const next=typeof fn==='function'?fn(old):{...old,...fn};if(imageSignature(old)!==imageSignature(next))imageChangeEpoch.current++;if(record){history.current.push(old);if(history.current.length>80)history.current.shift();future.current=[]}adopt(next);dirty.current=true;editSequence.current++;setSaveState('pending');try{localStorage.setItem('folio-recovery-'+next.id,JSON.stringify(next))}catch{}setTick(t=>t+1)}
